import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DYAmjhAm.js";const f=JSON.parse('{"title":"Interface: HttpResponse","description":"","frontmatter":{},"headers":[],"relativePath":"api/interfaces/HttpResponse.md","filePath":"api/interfaces/HttpResponse.md","lastUpdated":null}'),n={name:"api/interfaces/HttpResponse.md"};function s(c,e,i,d,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">breeze-client</a> / HttpResponse</p><h1 id="interface-httpresponse" tabindex="-1">Interface: HttpResponse <a class="header-anchor" href="#interface-httpresponse" aria-label="Permalink to &quot;Interface: HttpResponse&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L29" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:29</a></p><p>The response to one HTTP request Breeze made, as its data service adapter received it. Found on <a href="./ServerError#httpresponse">ServerError.httpResponse</a>, <a href="./QueryResult#httpresponse">QueryResult.httpResponse</a> and <a href="./SaveResult#httpresponse">SaveResult.httpResponse</a>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="config" tabindex="-1">config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;config&quot;">​</a></h3><blockquote><p><strong>config</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L32" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:32</a></p><p>The request that was sent: its <a href="./AjaxConfig">AjaxConfig</a> without the callbacks - <code>url</code>, <code>type</code> (the HTTP method), <code>params</code>, <code>data</code>, <code>headers</code> and so on.</p><hr><h3 id="data" tabindex="-1">data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;data&quot;">​</a></h3><blockquote><p><strong>data</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L35" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:35</a></p><p>The response body: the parsed JSON of a successful response, or the text of a failed one. Null when the request failed before any response arrived, or its body could not be read.</p><hr><h3 id="error" tabindex="-1">error? <a class="header-anchor" href="#error" aria-label="Permalink to &quot;error?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>error?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L38" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:38</a></p><p>Set only when the request failed: the error the transport threw if the request could not be completed or its body could not be read, otherwise the status text.</p><hr><h3 id="savecontext" tabindex="-1">saveContext? <a class="header-anchor" href="#savecontext" aria-label="Permalink to &quot;saveContext?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>saveContext?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L42" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:42</a></p><p>Set by Breeze on the response to a save request, where it is used to turn the server&#39;s per-entity errors into <a href="./EntityError">EntityError</a>s. Undefined for queries and metadata requests. Applications do not normally need it.</p><hr><h3 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h3><blockquote><p><strong>status</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L45" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:45</a></p><p>The HTTP status code. <code>0</code> when the request failed before any response arrived: offline, DNS, CORS, a server that is down, or an aborted request.</p><hr><h3 id="statustext" tabindex="-1">statusText? <a class="header-anchor" href="#statustext" aria-label="Permalink to &quot;statusText?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>statusText?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L48" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:48</a></p><p>The HTTP status text, such as &quot;Not Found&quot;. Empty when the server sent none (HTTP/2 never does), and set to the transport&#39;s error message when the request failed before any response arrived. May be absent with a custom ajax adapter.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="getheaders" tabindex="-1">getHeaders() <a class="header-anchor" href="#getheaders" aria-label="Permalink to &quot;getHeaders()&quot;">​</a></h3><blockquote><p><strong>getHeaders</strong>(<code>headerName</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/c2b3af9ef81a2eff9727726e0c824a491581b343/src/manager/entity-manager.ts#L52" target="_blank" rel="noreferrer">src/manager/entity-manager.ts:52</a></p><p>Returns the value of the named response header, or <code>null</code> if the response did not include it. Called with an empty name, returns an object holding every header, keyed by lower-case name. When no response arrived, returns <code>&quot;&quot;</code> for a name and <code>{}</code> without one.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="headername" tabindex="-1">headerName <a class="header-anchor" href="#headername" aria-label="Permalink to &quot;headerName&quot;">​</a></h5><p><code>string</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p>',44)])])}const b=t(n,[["render",s]]);export{f as __pageData,b as default};
